     ((-1 + \[Xi]w)^2*mass[MW]^4*(mass[MW]^2 - mass[MZ]^2)^2*
      (mass[MW]^2 - \[Xi]z*mass[MZ]^2)^2) - 
    (mass[MT]^4*(((2 - d)*mtad[{mass[MW], mass[MT], 0}, {1, 1, 0}])/
        (2*mass[MW]^2*(-mass[MT]^2 + mass[MW]^2)) + 
       ((-3 + d)*mtad[{mass[MW], mass[MT], 0}, {1, 1, 1}])/
        (-mass[MT]^2 + mass[MW]^2)))/((-1 + \[Xi]w)*mass[MW]^2*
      (mass[MW]^2 - mass[MZ]^2)*(mass[MW]^2 - \[Xi]z*mass[MZ]^2)) + 
    (mass[MT]^4*mtad[{Sqrt[\[Xi]w]*mass[MW], mass[MT], 0}, {1, 1, 1}])/
     ((-1 + \[Xi]w)^2*mass[MW]^4*(\[Xi]w*mass[MW]^2 - mass[MZ]^2)*
      (\[Xi]w*mass[MW]^2 - \[Xi]z*mass[MZ]^2)) - 
    (mass[MT]^4*mtad[{mass[MZ], mass[MT], 0}, {1, 1, 1}])/
     ((-1 + \[Xi]z)*mass[MZ]^2*(-mass[MW]^2 + mass[MZ]^2)^2*
      (-(\[Xi]w*mass[MW]^2) + mass[MZ]^2)) + 
    (mass[MT]^4*mtad[{Sqrt[\[Xi]z]*mass[MZ], mass[MT], 0}, {1, 1, 1}])/
     ((-1 + \[Xi]z)*mass[MZ]^2*(-mass[MW]^2 + \[Xi]z*mass[MZ]^2)^2*
      (-(\[Xi]w*mass[MW]^2) + \[Xi]z*mass[MZ]^2)))*NF[{MB}, {MT}])/
  (1024*cw^2*d*Pi^8*sw^4)
